/**
 * Monday.com Node - Version 2 - Zod Schema Factory
 * Exports a factory that unions all discriminator schemas.
 *
 * Schema helpers (z, expressionSchema, etc.) are passed as parameters
 * by the schema-validator, not imported from external files.
 *
 * @generated - CommonJS JavaScript for runtime loading
 */

const getBoardSchema = require('./resource_board/index.schema');
const getGroupSchema = require('./resource_group/index.schema');
const getColumnSchema = require('./resource_column/index.schema');
const getItemSchema = require('./resource_item/index.schema');
const getUpdateSchema = require('./resource_update/index.schema');

module.exports = function getSchema(helpers) {
  const { parameters, z } = helpers;
  // Apply discriminator default if not set
  const effectiveParams = parameters.resource === undefined ? { ...parameters, resource: 'item' } : parameters;
  return z.union([
    getBoardSchema({ ...helpers, parameters: effectiveParams }),
    getGroupSchema({ ...helpers, parameters: effectiveParams }),
    getColumnSchema({ ...helpers, parameters: effectiveParams }),
    getItemSchema({ ...helpers, parameters: effectiveParams }),
    getUpdateSchema({ ...helpers, parameters: effectiveParams }),
  ]);
};